-- Тема 13: Приоритет маршрутных ТС — топик id=13, категория id=12
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(12,13,'Обязан ли водитель легкового автомобиля уступить дорогу автобусу, начинающему движение от обозначенной остановки в населённом пункте?',
'["Да, если остановка обозначена знаком и разметкой, а автобус подаёт сигнал начала движения","Нет, у автобуса нет приоритета","Только если автобус пустой","Только вне населённых пунктов"]'::jsonb,0,
'При включении указателя поворота водитель автобуса или троллейбуса, отъезжающего от обозначенной остановки в населённом пункте, имеет преимущество, и водители других ТС обязаны уступить ему дорогу.',1),
(12,13,'Как должен действовать водитель при приближении транспортного средства с включённым проблесковым маячком синего цвета в сопровождении спецсигнала на перекрёстке?',
'["Уступить дорогу, независимо от сигнала светофора и направления движения","Продолжать движение, если горит зелёный сигнал","Пропускать только на нерегулируемых перекрёстках","Не обязан уступать, если едет по главной дороге"]'::jsonb,0,
'Водители обязаны уступить дорогу ТС с включённым проблесковым маячком синего цвета и специальным звуковым сигналом независимо от сигналов светофора и направления движения.',2),
(12,13,'Что означает включённый оранжевый (жёлтый) проблесковый маячок на ТС дорожных служб?',
'["Информирует о выполнении работ на дороге или наличии опасности, другие водители должны соблюдать осторожность","Означает право проезда без ограничений","Означает аварийную ситуацию с обязательной остановкой всех ТС","Не имеет значения для других водителей"]'::jsonb,0,
'Проблесковый маячок жёлтого или оранжевого цвета используется на ТС при выполнении работ по строительству, ремонту дорог или транспортировке крупногабаритных грузов — другие водители должны соблюдать особую осторожность.',3),
(12,13,'Кто из перечисленных транспортных средств имеет право двигаться в сопровождении автомобиля с включённым синим маячком без соблюдения отдельных требований дорожных знаков?',
'["Транспортные средства, входящие в состав организованной транспортной колонны","Любой легковой автомобиль","Только грузовые ТС","Такси"]'::jsonb,0,
'Механические ТС, движущиеся в составе организованной транспортной колонны в сопровождении автомобиля с включёнными синим и красным проблесковыми маячками, обязаны следовать за ведущим ТС, не меняя очерёдности следования.',4),
(12,13,'Обязаны ли пешеходы уступать дорогу транспортным средствам с включённым проблесковым маячком синего цвета и спецсигналом?',
'["Да, пешеходы обязаны уступить дорогу таким ТС","Нет, у пешеходов всегда приоритет","Только на пешеходных переходах","Только в тёмное время суток"]'::jsonb,0,
'При приближении ТС с включённым проблесковым маячком синего цвета и специальным звуковым сигналом пешеходы обязаны воздержаться от перехода дороги, а начавшие переход — незамедлительно освободить проезжую часть.',5);

-- Тема 14: Перевозка людей и грузов — топик id=14, категория id=13
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(13,14,'С какого возраста разрешена перевозка детей на переднем сиденье легкового автомобиля с использованием только штатного ремня безопасности (без детского кресла)?',
'["С 12 лет","С 7 лет","С 5 лет","С 3 лет"]'::jsonb,0,
'Перевозка детей до 7 лет в легковом автомобиле на переднем сиденье возможна только с использованием детских удерживающих устройств. С 7 до 11 лет включительно на переднем сиденье также обязательно детское кресло, а на заднем допускается ремень безопасности при определённых условиях; полностью только ремнём безопасности без кресла — с 12 лет.',1),
(13,14,'Разрешена ли перевозка людей в кузове грузового автомобиля вне кабины?',
'["Разрешена, если кузов оборудован в соответствии с установленными требованиями для перевозки людей","Запрещена в любом случае","Разрешена без ограничений","Разрешена только для родственников водителя"]'::jsonb,0,
'Перевозка людей в кузове грузового автомобиля с бортовой платформой разрешена, если кузов оборудован для перевозки людей согласно установленным требованиям (сиденья, поручни и т.д.).',2),
(13,14,'Как должен быть обозначен груз, выступающий за габариты ТС более чем на 1 м сзади?',
'["Опознавательным знаком Крупногабаритный груз, а в тёмное время суток — дополнительно фонарём или световозвращателем красного цвета","Обозначение не требуется","Достаточно включить аварийную сигнализацию","Достаточно флажка любого цвета"]'::jsonb,0,
'Если перевозимый груз выступает за габариты ТС спереди или сзади более чем на 1 метр, он должен быть обозначен опознавательными знаками, а в тёмное время суток и в условиях недостаточной видимости — фонарями или световозвращателями.',3),
(13,14,'Разрешается ли водителю мотоцикла перевозить пассажира без мотошлема?',
'["Нет, водитель и пассажир мотоцикла обязаны быть в застёгнутых мотошлемах","Да, если поездка короткая","Да, вне населённых пунктов","Да, если пассажир старше 18 лет"]'::jsonb,0,
'Водителям мотоциклов и мопедов, а также их пассажирам запрещено движение без застёгнутого мотошлема.',4),
(13,14,'Влияет ли перевозимый груз на видимость номерных знаков и световых приборов?',
'["Груз не должен закрывать номерные знаки, световые приборы и ограничивать обзорность водителю","Груз может закрывать номерные знаки, если ТС временно не эксплуатируется","Требование распространяется только на грузовые ТС","Требование действует только ночью"]'::jsonb,0,
'Перевозимый груз не должен ограничивать водителю обзор, ухудшать устойчивость и управляемость ТС, закрывать световые приборы, номерные знаки и создавать шум.',5);
